L[101]=[
  ("पाठ-101 («Meta का unit economics») का सार क्या है?","Meta-विज्ञापन-ख़र्च को प्रति-ऑर्डर या प्रति-बिक्री में तोड़कर, सीधे Contribution Margin से घटाना चाहिए","IndiaMART एक B2B (Business-to-Business) थोक-बाज़ार है, जहाँ न ख़रीदार आम ग्राहक (B2C) है, न सरकार (B2G)","प्रोफ़ाइल में दुकान का नाम, फ़ोटो/लोगो, श्रेणी, पता, खुलने का समय, वेबसाइट (अगर है), और छोटा विवरण भरो","अब समय है इन सभी टुकड़ों को जोड़कर एक संपूर्ण, कम-से-कम डेमो-रूप में काम करने वाली अपनी दुकान बनाने का"),
  ("«Meta का unit economics» (पाठ-101) की आम ग़लती क्या है?","ROAS का बड़ा नंबर देखकर बिना मार्जिन-जाँच के विज्ञापन-बजट बढ़ा देना","काम पूरा होने के बाद, कभी रिपोर्ट न भेजना, ग्राहक को अंधेरे में रखना","एक ही creative पूरे त्योहार-चक्र में चलाना — थकान से नतीजा गिरता है","जटिल Flow ख़ुद बनाने की ज़िद, बिना BSP-सहायक से पूछे — घंटों बर्बाद"),
  ("कौन-सी ग़लती «विज्ञापन ख़र्च बनाम मार्जिन» वाले पाठ-101 में बताई गई?","30%-सीमा पार होने पर भी नज़रअंदाज़ करना, \"बिक्री तो बढ़ रही है\" सोचकर","त्योहार-भीड़ में RTO-सतर्कता कम करना, जबकि वहीं सबसे ज़्यादा ज़रूरी है","हर फ़ोटो पर बहुत ज़्यादा सुधार करके फ़ोटो नक़ली/कार्टून जैसी बना देना","\"अपनी दुकान\" बनाकर, मार्केटप्लेस पूरी तरह छोड़ देना, दोहरा-लाभ गँवाना"),
  ("«Meta का unit» (पाठ-101) की सुरक्षा-सलाह क्या है?","यह गणित-पन्ना दुकान की आंतरिक जानकारी है — लागत-मार्जिन किसी बाहरी व्यक्ति (प्रतियोगी सहित) से साझा न करें","किसी भी उदाहरण-कहानी को असली, सत्यापित स्रोत से ही साझा करें, गढ़ी हुई/असत्यापित कहानियों को असली न बताएँ","अगर अपनी रिटर्न-नीति के क़ानूनी-सही होने पर संदेह हो, किसी क़ानूनी-सलाहकार से एक बार जाँच करवाना बेहतर है","अपने ग्राहक-रजिस्टर में सिर्फ़ ज़रूरी जानकारी रखें — यह पाठ-263/283 के DPDP-सिद्धांत का यहाँ भी दोहराव है"),
  ("«Meta-विज्ञापन-ख़र्च को प्रति-ऑर्डर या प्रति-बिक्री में तोड़कर» — किस पाठ की बात?","Meta का unit-economics — विज्ञापन-ख़र्च बनाम मार्जिन","Business Profile पूरी करना — श्रेणी, गुण, सेवा, फ़ोटो","WhatsApp Flows — चैट-भीतर फ़ॉर्म, बुकिंग, पता-संग्रह","सेलर-योजनाएँ — Udyam-लाभ, PM-Vishwakarma, MSME-सहारे"),
]
L[102]=[
  ("पाठ-102 («Meta मासिक रख रखाव») का सार क्या है?","Meta-मंच (Facebook, Instagram, Ads) के लिए भी वैसा ही तीन-स्तर काम-कार्ड चाहिए","Business-भुगतान ऐप (जैसे कुछ मशहूर भुगतान-सेवाएँ) हर लेन-देन का अपने-आप रिकॉर्ड","Flows से ग्राहक चैट को छोड़े बिना, ऐप के भीतर ही खुलने वाले असली फ़ॉर्म पर नाम","अपनी दुकान पर कैटलॉग बनाना उसी Product Data Feed सिद्धांत का व्यावहारिक अमल है"),
  ("«Meta मासिक रख रखाव» (पाठ-102) की आम ग़लती क्या है?","WhatsApp और Meta के काम-कार्ड को अलग-अलग पन्नों पर रखना — भूलने की जड़","प्रोफ़ाइल में झूठा अनुभव/कौशल दिखाना, बाद में पकड़े जाने पर भरोसा टूटना","त्योहार-भीड़ में RTO-सतर्कता कम करना, जबकि वहीं सबसे ज़्यादा ज़रूरी है","बहुत कम गुण (सिर्फ़ एक-दो) जोड़ना, जिससे कोई बारीक़ सवाल मेल नहीं खाता"),
  ("दूसरी ग़लती कौन-सी — पाठ-102 «रखाव काम कार्ड»?","काम-कार्ड बनाकर कभी न खोलना (पाठ-84 की भी यही सबसे आम ग़लती)","सुर बहुत औपचारिक/उबाऊ रखना जबकि दुकान का स्वभाव दोस्ताना है","कम DRR वाले उत्पाद पर ज़्यादा निवेश करते रहना, बदलाव न करना","मासिक रख-रखाव लेते समय, नियमित-प्रतिबद्धता का महत्व न समझना"),
  ("«Meta मासिक रख» (पाठ-102) की सुरक्षा-सलाह क्या है?","काम-कार्ड में ग्राहक-निजी जानकारी नहीं, सिर्फ़ प्रक्रिया व गिनती। जहाँ यह पन्ना रखा जाए, वहाँ दुकान-मालिक की जानकारी में हो","सौंदर्य-उत्पाद की अवयव-सूची व समाप्ति-तारीख़ हमेशा सच्ची-सटीक रखें — ग़लत जानकारी ग्राहक-स्वास्थ्य को नुक़सान पहुँचा सकती है","पता में घर का पूरा, सटीक पता (मकान-नंबर तक) की बजाय इलाक़ा/मोहल्ला-स्तर पर्याप्त है अगर आप घर से सेवा-सहायक का काम करते हैं","Flipkart Seller Hub का password व वित्तीय-सेटिंग दुकान-मालिक के नियंत्रण में रखें — पाठ-142 का हर नियम यहाँ भी उतना ही लागू"),
  ("पाठ-102 का शीर्षक क्या है?","Meta मासिक रख-रखाव काम-कार्ड","ONDC क्या — UPI जैसा खुला जाल","Sponsored Brands/Display झलक","courier-चयन — दर, पहुँच, COD"),
]
